import type { ComponentProps } from '@solidjs/web'
import {
  createDateInputController,
  DateInput as UiDateInput,
  DateInputSegment as UiDateInputSegment,
} from '@ui-sdk/solid/date-input'
import { omit } from 'solid-js'

import './date-input.css'

export { createDateInputController }

export type DateInputAppearance = 'small' | 'base' | 'large'
export type DateInputSurface = 'base' | 'layer-1' | 'invisible'

type UiDateInputProps = ComponentProps<typeof UiDateInput>

export type DateInputProps = Omit<UiDateInputProps, 'class' | 'render'> & {
  /** Control height. Defaults to `base` (28px). */
  appearance?: DateInputAppearance
  /** Background fill. Defaults to `base`. */
  surface?: DateInputSurface
  /** Forces the invalid outline without overriding built-in range validation. */
  invalid?: boolean
  class?: UiDateInputProps['class']
  render?: UiDateInputProps['render']
}

export function DateInput(props: DateInputProps) {
  const rest = omit(props, 'appearance', 'surface', 'invalid', 'class', 'render')

  return (
    <UiDateInput
      {...rest}
      class={props.class}
      render={props.render}
      data-appearance={props.appearance ?? 'base'}
      data-surface={props.surface ?? 'base'}
      data-user-invalid={props.invalid ? '' : undefined}
    />
  )
}

type UiDateInputSegmentProps = ComponentProps<typeof UiDateInputSegment>

export type DateInputSegmentProps = Omit<
  UiDateInputSegmentProps,
  'class' | 'render'
> & {
  class?: UiDateInputSegmentProps['class']
  render?: UiDateInputSegmentProps['render']
}

export function DateInputSegment(props: DateInputSegmentProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiDateInputSegment {...rest} class={props.class} render={props.render} />
  )
}

@layer components {
  [data-slot="date-input"] {
    box-sizing: border-box;
    display: inline-flex;
    flex-direction: row;
    align-items: center;
    gap: 0;
    min-width: 0;
    height: 28px;
    padding-block: 0;
    padding-inline: 8px;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    color: var(--v2-text-text-base);
    font-family: var(--font-family-sans);
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    font-variant-numeric: tabular-nums;
    font-variation-settings: "slnt" 0;
    cursor: text;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="date-input"][data-appearance="small"] {
    height: 24px;
    padding-inline: 6px;
  }

  [data-slot="date-input"][data-appearance="large"] {
    height: 32px;
    padding-inline: 10px;
  }

  [data-slot="date-input"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="date-input"][data-surface="invisible"] {
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-slot="date-input"]:hover:not(
        [data-disabled],
        [data-invalid],
        [data-user-invalid],
        [data-surface="invisible"]
      ):not(:has([data-slot="date-input-segment"]:focus)) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }

    [data-slot="date-input"][data-surface="invisible"]:hover:not(
        [data-disabled],
        [data-invalid],
        [data-user-invalid]
      ):not(:has([data-slot="date-input-segment"]:focus)) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="date-input"]:has([data-slot="date-input-segment"]:focus):not(
      [data-disabled],
      [data-invalid],
      [data-user-invalid]
    ) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="date-input"]:is([data-invalid], [data-user-invalid]):not(
      [data-disabled]
    ) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
    color: var(--v2-state-fg-danger);
  }

  [data-slot="date-input"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="date-input-segment"][data-type="literal"] {
    padding-inline: 1px;
    color: var(--v2-text-text-faint);
    white-space: pre;
    user-select: none;
  }

  [data-slot="date-input-segment"]:not([data-type="literal"]) {
    box-sizing: border-box;
    width: calc(2ch + 6px);
    height: 20px;
    padding: 0 3px;
    margin: 0;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: inherit;
    font: inherit;
    font-variant-numeric: tabular-nums;
    text-align: center;
    caret-color: transparent;
    outline: none;
    transition:
      background 85ms ease-out,
      color 85ms ease-out;
  }

  [data-slot="date-input"][data-appearance="small"]
    [data-slot="date-input-segment"]:not([data-type="literal"]) {
    height: 18px;
  }

  [data-slot="date-input"][data-appearance="large"]
    [data-slot="date-input-segment"]:not([data-type="literal"]) {
    height: 22px;
  }

  [data-slot="date-input-segment"][data-type="year"] {
    width: calc(4ch + 6px);
  }

  [data-slot="date-input-segment"][data-type="dayPeriod"] {
    width: calc(2.8ch + 6px);
    margin-inline-start: 2px;
  }

  [data-slot="date-input-segment"]:not([data-type="literal"])::placeholder {
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="date-input-segment"][data-empty]:not([data-type="literal"]) {
    color: var(--v2-text-text-faint);
  }

  [data-slot="date-input-segment"]:not([data-type="literal"])::selection {
    background: transparent;
  }

  [data-slot="date-input-segment"]:not([data-type="literal"]):focus {
    background: var(--v2-state-bg-info);
    color: var(--v2-state-fg-info);
  }

  [data-slot="date-input-segment"]:not([data-type="literal"]):focus::placeholder {
    color: var(--v2-state-fg-info);
    opacity: 0.75;
  }

  [data-slot="date-input"]:is([data-invalid], [data-user-invalid]):not(
      [data-disabled]
    )
    [data-slot="date-input-segment"]:not([data-type="literal"]):focus {
    background: var(--v2-state-bg-danger);
    color: var(--v2-state-fg-danger);
  }

  [data-slot="date-input"]:is([data-invalid], [data-user-invalid]):not(
      [data-disabled]
    )
    [data-slot="date-input-segment"]:not([data-type="literal"])::placeholder {
    color: var(--v2-state-fg-danger);
    opacity: 0.75;
  }

  [data-slot="date-input-segment"][data-disabled] {
    cursor: not-allowed;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="date-input"],
    [data-slot="date-input-segment"] {
      transition: none;
    }
  }
}
